@startuml

class Home {
  + Name : string
}

class Department {
  + Name : string
}

class Room {
  + Number : int
}

class Bed {
  + Category : string
  + Price : double
}

class Inhabitant {
  + Name : string
  + RegistrationDate : date
  + NeedsHelpForEating : boolean
  + NeedsHelpForDressing : boolean
  + NeedsPersonalCare : boolean
}

class StayCategory {
  + Type : string
  + Price : double
}

class Proposal {
  + Status : string
  + AcceptanceDate : date
}

class WaitingList {
  + Position : int
}

class Invoice {
  + Total : double
  + OutstandingAmount : double
  + PaymentReceived : boolean
}

class CreditNote {}

Home "1" -- "*" Department
Department "1" -- "*" Room
Room "1" -- "*" Bed
Inhabitant "0..*" -- "*" StayCategory
StayCategory "1" -- "*" Proposal
Proposal "1" -- "*" Inhabitant
Inhabitant "1" -- "*" WaitingList
WaitingList "1" -- "*" Proposal
Proposal "1" -- "*" Invoice
Invoice "1" ..> CreditNote

@enduml

